const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const token=()=>document.querySelector('#admin-token').value;
const headers=()=>({'Content-Type':'application/json',...(token()?{Authorization:`Bearer ${token()}`}:{})});
const anchors={birth:'Narodziny',pregnancy:'Początek ciąży',birthCardDate:'Wystawienie karty urodzenia',peselDate:'Nadanie PESEL',parentalLeaveDate:'Początek urlopu',dueDate:'Termin porodu'};
function ruleFields(prefix,rule){return `<div class="rules"><label>Zdarzenie<select name="${prefix}Anchor">${Object.entries(anchors).map(([id,name])=>`<option value="${id}" ${id===rule.anchor?'selected':''}>${name}</option>`).join('')}</select></label><label>Miesiące<input name="${prefix}Months" type="number" min="-24" max="24" value="${rule.months||0}"></label><label>Dni<input name="${prefix}Days" type="number" min="-1000" max="1000" value="${rule.days||0}"></label></div>`;}
async function load(){
  const message=document.querySelector('#status');message.textContent='Wczytywanie…';
  try{const r=await fetch('/api/review',{headers:headers()});const data=await r.json();if(!r.ok)throw new Error(data.error||'Błąd odczytu.');
    const sources=data.sources.filter(s=>s.pending||s.status==='missing'||s.newLinks?.length);
    document.querySelector('#reviews').innerHTML=sources.map(s=>`<article data-source="${s.id}"><h2>${esc(s.name)}</h2><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Otwórz oficjalne źródło ↗</a><p class="notice">Stan: ${esc(s.status)}. Zmiana wykryta: ${esc(s.pending?.detectedAt||s.lastCheckedAt)}</p>${s.newLinks?.length?`<details><summary>Nowe powiązane dokumenty (${s.newLinks.length})</summary>${s.newLinks.map(link=>`<p><a href="${esc(link)}" target="_blank" rel="noopener noreferrer">${esc(link)}</a></p>`).join('')}</details>`:''}<details><summary>Poprzednia zapisana treść</summary><pre>${esc(s.acceptedText)}</pre></details><details><summary>Nowa treść</summary><pre>${esc(s.pending?.text||'Źródło zniknęło — wskaż działający oficjalny adres.')}</pre></details><form data-hash="${esc(s.pending?.hash||s.currentHash)}"><label>Adres źródła (możesz wskazać nowy oficjalny adres)<input type="url" name="replacementUrl" value="${esc(s.url)}" required></label><label>Fragment do podświetlenia<input name="quote" maxlength="250" value="${esc(s.quote)}" required></label><label>Nazwa sekcji<input name="section" maxlength="250" value="${esc(s.section)}" required></label>${data.events.filter(e=>e.source===s.id||e.source==='vaccines'&&s.id.startsWith('vaccines')).map(e=>{const v=e.versions?.at(-1)||e;return `<fieldset data-event="${e.id}"><legend>${esc(e.title)}</legend><label>Zweryfikowany opis<textarea name="description">${esc(v.description)}</textarea></label><label>Nowe zasady obowiązują od<input name="validFrom" type="date" value="${new Date().toISOString().slice(0,10)}" required></label>${e.recurring==='800'?`<label>Coroczny początek (MM-DD)<input name="calendarStart" pattern="[0-9]{2}-[0-9]{2}" value="${esc((v.calendarWindow||e.calendarWindow||{start:'02-01'}).start)}" required></label><label>Coroczny koniec (MM-DD)<input name="calendarEnd" pattern="[0-9]{2}-[0-9]{2}" value="${esc((v.calendarWindow||e.calendarWindow||{end:'06-30'}).end)}" required></label>`:''}<strong>Początek okresu</strong>${ruleFields('start',v.start||e.start)}<strong>Koniec okresu</strong>${ruleFields('end',v.end||e.end)}</fieldset>`;}).join('')}<label><input type="checkbox" name="verified" style="width:auto;min-height:0" required> Sprawdzono treść w źródle i właściwą datę obowiązywania.</label><button class="primary" type="submit">Zatwierdź zweryfikowaną wersję</button><p class="notice" role="status"></p></form></article>`).join('')||'<p>Brak zmian oczekujących na sprawdzenie.</p>';
    message.textContent=`Źródła do przeglądu: ${sources.length}`;
    document.querySelectorAll('article form').forEach(form=>form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;try{
      const patches=[...form.querySelectorAll('[data-event]')].map(field=>{const read=name=>field.querySelector(`[name="${name}"]`).value;const rule=prefix=>({anchor:read(prefix+'Anchor'),months:Number(read(prefix+'Months')),days:Number(read(prefix+'Days'))});return {id:field.dataset.event,description:read('description'),validFrom:read('validFrom'),start:rule('start'),end:rule('end'),...(field.querySelector('[name=calendarStart]')?{calendarWindow:{start:read('calendarStart'),end:read('calendarEnd')}}:{})};});
      const res=await fetch('/api/review',{method:'POST',headers:headers(),body:JSON.stringify({sourceId:form.closest('article').dataset.source,hash:form.dataset.hash,replacementUrl:form.elements.replacementUrl.value,quote:form.elements.quote.value,section:form.elements.section.value,patches})});const result=await res.json();if(!res.ok)throw new Error(result.error);await load();
    }catch(error){form.querySelector('[role="status"]').textContent=error.message;}finally{button.disabled=false;}}));
  }catch(error){message.textContent=error.message;}
}
document.querySelector('#reload').addEventListener('click',load);load();
